"""Inventory the physical M812 GLBs, including separate LOD budgets and licenses."""
import json,struct,hashlib
from pathlib import Path
root=Path('public/assets');records=[]
metadata=[
 ('models/weapons/m9-service.glb','Beretta 92 / M9','Pixel32','https://opengameart.org/content/textured-pistol','CC-BY-3.0'),
 ('models/viewmodels/operator-arms.glb','Operator arms','para / MakeHuman team; project adaptation','https://opengameart.org/content/fps-arms-rigged-only','CC0-1.0'),
 ('models/characters/infected-worker.glb','Contaminated worker and fitted vest','Pixelhouse team; project adaptation','https://opengameart.org/content/zombie','CC-BY-3.0'),
 ('models/characters/infected-hunter.glb','Thin Zombie / Predator','Rosswet Mobile','https://opengameart.org/content/thin-zombie-awake-zombie-asset','CC-BY-3.0')]
for filename,name,author,source,license in metadata:
 data=(root/filename).read_bytes();g=json.loads(data[20:20+struct.unpack_from('<I',data,12)[0]])
 def triangles(mesh):return sum(g['accessors'][p['indices']]['count']//3 if 'indices' in p else g['accessors'][p['attributes']['POSITION']]['count']//3 for p in mesh['primitives'])
 per_node={n['name']:triangles(g['meshes'][n['mesh']]) for n in g['nodes'] if 'mesh' in n}
 records.append(dict(name=name,path=filename,format='GLB 2.0',author=author,source=source,license=license,
  bytes=len(data),sha256=hashlib.sha256(data).hexdigest(),triangles=sum(triangles(m) for m in g['meshes']),trianglesByNode=per_node,
  skins=len(g.get('skins',[])),joints=[len(s['joints']) for s in g.get('skins',[])],textures=[i.get('name','embedded') for i in g.get('images',[])],
  animations=[a['name'] for a in g.get('animations',[])],status='integrated-review-pending'))
output={'version':'M8.1.2','assets':records,'runtimeExternalAssets':False,'historicalFiles':'M811 GLBs retained but not loaded by MODEL_PATHS','roomSurfaces':'Original local CanvasTextures generated by RoomSurfaces.ts; CC0','approval':'Visual review and real desktop GPU performance still required'}
(root/'manifests/visual-assets-m812.json').write_text(json.dumps(output,indent=2)+'\n');print(json.dumps(records,indent=2))
